SELECT region,SUM(CASE WHEN stage='Closed Won' THEN amount ELSE 0 END) AS won_revenue, SUM(CASE WHEN stage NOT IN ('Closed Won','Closed Lost') THEN 1 ELSE 0 END) AS open_opportunities, CASE WHEN SUM(CASE WHEN stage NOT IN ('Closed Won','Closed Lost') AND amount IS NULL THEN 1 ELSE 0 END)>0 THEN NULL ELSE SUM(CASE WHEN stage NOT IN ('Closed Won','Closed Lost') THEN amount ELSE 0 END) END AS open_pipeline FROM fact_opportunities GROUP BY region ORDER BY won_revenue DESC;
